  DateTime? _checkIn;
  DateTime? _checkOut;

  int _adults = 2;
  int _children = 0;
  int _infants = 0;

  static DateTime _dayOf(DateTime d) => DateTime(d.year, d.month, d.day);

  DateTime get _today => _dayOf(DateTime.now());
  DateTime get _lastSelectable =>
      DateTime(_today.year, _today.month + _monthsAhead, _today.day);

  @override
  void initState() {
    super.initState();
    _month = DateTime(_today.year, _today.month);
