  }

  Future<void> _load() async {
    try {
      final StayListing? listing =
          await StayListingService.instance.byId(widget.listingId);

      // Blocked nights are fetched ONCE for the whole selectable window rather
      // than per month. Paging the calendar would otherwise fire a callable on
      // every arrow tap, and a guest flicking through months would produce a
      // dozen calls and a calendar that flickers between "free" and "taken" as
      // each one lands.
      final Set<DateTime> blocked =
          await StayAvailabilityService.instance.blockedNights(
        listingId: widget.listingId,
        from: _today,
        to: _lastSelectable,
      );

      if (!mounted) return;
      setState(() {
        _listing = listing;
        _blocked = blocked.map(_dayOf).toSet();
        _adults = 2;
        _loading = false;
        _loadError = listing == null ? 'notfound' : null;
      });
    } catch (e) {
      if (!mounted) return;
      // A failed availability read must NOT leave the calendar open and
      // apparently empty — every night would look free and the guest would
      // pick one that is already taken, only to be refused by the server at
      // the last step.
      setState(() {
        _loading = false;
        _loadError = 'error';
      });
    }
  }

  // ── Selection ────────────────────────────────────────────────────────────

  bool _isBlocked(DateTime d) => _blocked.contains(_dayOf(d));

  bool _isSelectable(DateTime d) {
    final DateTime day = _dayOf(d);
    if (day.isBefore(_today)) return false;
    if (day.isAfter(_lastSelectable)) return false;
    return !_isBlocked(day);
  }

  /// True when every NIGHT from [from] up to but not including [to] is free.
  bool _rangeIsFree(DateTime from, DateTime to) {
    for (DateTime d = _dayOf(from);
        d.isBefore(_dayOf(to));
        d = d.add(const Duration(days: 1))) {
      if (_isBlocked(d)) return false;
    }
    return true;
  }

  void _onDayTapped(DateTime day) {
    final DateTime d = _dayOf(day);
    if (!_isSelectable(d)) return;

    setState(() {
      final DateTime? inD = _checkIn;

      // Nothing chosen, or a complete stay already chosen: start again.
      if (inD == null || _checkOut != null) {
        _checkIn = d;
        _checkOut = null;
        return;
      }

      // Tapping the arrival date again, or an earlier one, moves arrival.
      if (!d.isAfter(inD)) {
        _checkIn = d;
        return;
      }

      // A departure date is only accepted if nothing in between is taken.
      // Silently moving the arrival instead would be confusing, so an
      // unreachable departure just restarts the selection from that day.
      if (_rangeIsFree(inD, d)) {
        _checkOut = d;
      } else {
        _checkIn = d;
        _checkOut = null;
      }
    });
  }

  bool _isInRange(DateTime d) {
    final DateTime? a = _checkIn;
    final DateTime? b = _checkOut;
    if (a == null || b == null) return false;
    final DateTime day = _dayOf(d);
    return day.isAfter(a) && day.isBefore(b);
  }

  int get _nights => (_checkIn != null && _checkOut != null)
      ? _checkOut!.difference(_checkIn!).inDays
      : 0;

  int get _maxGuests => _listing?.maxGuests ?? 1;
  bool get _atGuestLimit => (_adults + _children) >= _maxGuests;

  // ── Build ────────────────────────────────────────────────────────────────

