              const SizedBox(height: 24),
              if (_loadError != 'notfound')
                ElevatedButton(
                  onPressed: () {
                    setState(() {
                      _loading = true;
                      _loadError = null;
                    });
                    _load();
                  },
                  style: ElevatedButton.styleFrom(
