  Widget _buildCalendarGrid() {
    final DateTime first = DateTime(_month.year, _month.month);
    final int daysInMonth =
        DateTime(_month.year, _month.month + 1, 0).day;

    // Monday-first. DateTime.weekday is 1=Mon..7=Sun, so the number of blank
    // cells before the 1st is weekday-1.
    final int leading = first.weekday - 1;
    final int cells = leading + daysInMonth;
    final int rows = (cells / 7).ceil();

    return Column(
      children: [
        for (int r = 0; r < rows; r++)
          Row(
            children: [
              for (int c = 0; c < 7; c++)
                Expanded(child: _buildDayCell(r * 7 + c - leading + 1)),
            ],
          ),
      ],
    );
  }

  Widget _buildDayCell(int dayNumber) {
    final int daysInMonth = DateTime(_month.year, _month.month + 1, 0).day;
    if (dayNumber < 1 || dayNumber > daysInMonth) {
      return const SizedBox(height: 44);
    }

    final DateTime day = DateTime(_month.year, _month.month, dayNumber);
    final bool selectable = _isSelectable(day);
    final bool isCheckIn = _checkIn != null && _dayOf(_checkIn!) == day;
    final bool isCheckOut = _checkOut != null && _dayOf(_checkOut!) == day;
    final bool inRange = _isInRange(day);
    final bool isEnd = isCheckIn || isCheckOut;

    return SizedBox(
      height: 44,
      child: InkWell(
        onTap: selectable ? () => _onDayTapped(day) : null,
        borderRadius: BorderRadius.circular(8),
        child: Container(
          margin: const EdgeInsets.all(2),
          decoration: BoxDecoration(
            color: isEnd
                ? GoOutsColors.primaryBlue
                : inRange
                    ? GoOutsColors.paleBlueTint
                    : Colors.transparent,
            borderRadius: BorderRadius.circular(8),
          ),
          child: Center(
            child: Text(
              '$dayNumber',
              style: GoogleFonts.inter(
                fontSize: 14,
                fontWeight: isEnd ? FontWeight.w700 : FontWeight.w500,
                color: isEnd
                    ? Colors.white
                    : !selectable
                        // Struck through, not merely greyed: a taken night has
                        // to be distinguishable from a pale one at a glance.
                        ? GoOutsColors.bodyText.withValues(alpha: 0.35)
                        : GoOutsColors.deepNavy,
                decoration: (!selectable && !_dayOf(day).isBefore(_today))
                    ? TextDecoration.lineThrough
                    : TextDecoration.none,
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildSelectionHint() {
