  void _continue() {
    if (_nights <= 0) return;
    Navigator.of(context).pushNamed(
      StayRoutes.checkout,
      arguments: <String, dynamic>{
        'request': StayBookingRequest(
          listingId: widget.listingId,
          checkIn: _checkIn!,
          checkOut: _checkOut!,
          adults: _adults,
          children: _children,
          infants: _infants,
        ),
      },
    );
